// Index the pool once. The model sees indices only - code resolves them
// back to finding ids, so it cannot invent or drop a citation.
const findings = $('Aggregate Pool').first().json.findings || [];
const emergentRows = $('Aggregate Emergent').first().json.emergent || [];

const findingsList = findings.map((f, i) => ({
  i: i,
  question: f.question,
  section: f.section,
  name: f.name,
  definition: f.definition,
  is_minority: f.is_minority,
  sessions: Number(f.sessions) || 0,
}));

// Dedupe the improvised questions by text - L1 inserts one row per session
// that raised it, so the same question appears many times.
const seen = new Map();
for (const e of emergentRows) {
  const key = String(e.question || '').trim().toLowerCase();
  if (!key) { continue; }
  if (!seen.has(key)) { seen.set(key, { question: e.question, asked_in_sessions: Number(e.asked_in_sessions) || 1, summaries: [] }); }
  const row = seen.get(key);
  if (e.summary && row.summaries.length < 4) { row.summaries.push(e.summary); }
}
const emergentList = Array.from(seen.values());

return [{ json: { findings_list: findingsList, emergent_list: emergentList, findings_total: findingsList.length, emergent_total: emergentList.length } }];

