// Resolve indices to real finding ids and compute every count here. The model
// states no numbers: it cites, code counts. So an answer claiming 'answered'
// while resting on two findings from one participant is visible as such.
const raw = $input.first().json;
const out = raw.output || raw;
const rq = $('Loop Research Questions').first().json;
const findings = $('Aggregate Pool').first().json.findings || [];

const idxs = Array.isArray(out.finding_indexes) ? out.finding_indexes : [];
const seen = new Set();
const resolved = [];
let rejected = 0;
for (const rawIdx of idxs) {
  const i = Number(rawIdx);
  if (!Number.isInteger(i) || i < 0 || i >= findings.length) { rejected++; continue; }
  if (seen.has(i)) { continue; }
  seen.add(i);
  resolved.push(findings[i]);
}

const questions = new Set();
let sessions = 0;
const ids = [];
for (const f of resolved) {
  ids.push(String(f.finding_id));
  questions.add(String(f.question_id));
  sessions = Math.max(sessions, Number(f.sessions) || 0);
}

// An answer that cites nothing cannot be 'answered' or 'partial', whatever the
// model said. The citation list is the evidence.
const claimed = String(out.status || 'parked');
let status = claimed;
if (resolved.length === 0) { status = 'parked'; }

// The model sometimes embeds the raw finding indices in the prose, e.g.
// "...maintain trust and control [20,21,23,138]". Those are meaningless to a
// reader and this text goes into a presentation. Citations travel separately
// in finding_indexes and are resolved above, so strip them here rather than
// asking the prompt not to emit them - code can guarantee it.
let answer = String(out.answer || '');
answer = answer.replace(/\s*\[\s*\d+(\s*,\s*\d+)*\s*\]/g, '');
answer = answer.replace(/\s+([.,;:])/g, '$1').replace(/[ \t]{2,}/g, ' ').trim();

return [{ json: {
  research_question_id: rq.id,
  research_question: rq.text,
  status: status,
  answer: answer,
  finding_ids: ids,
  findings_count: ids.length,
  questions_count: questions.size,
  sessions_count: sessions,
  indexes_rejected: rejected,
  status_downgraded: status !== claimed,
  run_id: $('Fetch Evidence Pool').first().json.run_id,
  source_run_id: $('Fetch Evidence Pool').first().json.source_run_id
} }];
